config:
{
  "apps": {
    "http": {
      "servers": {
        "keelson": {
          "client_ip_headers": [
            "CF-Connecting-IP"
          ],
          "errors": {
            "routes": [
              {
                "handle": [
                  {
                    "handler": "headers",
                    "response": {
                      "set": {
                        "X-Frame-Options": [
                          "DENY"
                        ]
                      }
                    }
                  },
                  {
                    "handler": "rewrite",
                    "uri": "/404.html"
                  },
                  {
                    "handler": "file_server",
                    "index_names": [
                      "index.html"
                    ],
                    "root": "/var/www/static"
                  }
                ],
                "match": [
                  {
                    "expression": "{http.error.status_code} == 404",
                    "host": [
                      "static.example.com"
                    ]
                  }
                ],
                "terminal": true
              }
            ]
          },
          "listen": [
            ":443"
          ],
          "logs": {
            "default_logger_name": "access"
          },
          "routes": [
            {
              "handle": [
                {
                  "handler": "reverse_proxy",
                  "headers": {
                    "request": {
                      "set": {
                        "X-Forwarded-For": [
                          "{http.vars.client_ip}"
                        ]
                      }
                    }
                  },
                  "upstreams": [
                    {
                      "dial": "127.0.0.1:9000"
                    }
                  ]
                }
              ],
              "match": [
                {
                  "host": [
                    "api.example.com"
                  ]
                }
              ],
              "terminal": true
            },
            {
              "handle": [
                {
                  "handler": "reverse_proxy",
                  "headers": {
                    "request": {
                      "set": {
                        "X-Forwarded-For": [
                          "{http.vars.client_ip}"
                        ]
                      }
                    }
                  },
                  "upstreams": [
                    {
                      "dial": "127.0.0.1:4000"
                    }
                  ]
                }
              ],
              "match": [
                {
                  "host": [
                    "legacy.example.com"
                  ]
                }
              ],
              "terminal": true
            },
            {
              "handle": [
                {
                  "handler": "static_response",
                  "headers": {
                    "Location": [
                      "https://new.example.com{http.request.uri}"
                    ]
                  },
                  "status_code": 301
                }
              ],
              "match": [
                {
                  "host": [
                    "old.example.com"
                  ]
                }
              ],
              "terminal": true
            },
            {
              "handle": [
                {
                  "handler": "subroute",
                  "routes": [
                    {
                      "handle": [
                        {
                          "handler": "headers",
                          "response": {
                            "set": {
                              "X-Frame-Options": [
                                "DENY"
                              ]
                            }
                          }
                        }
                      ]
                    },
                    {
                      "handle": [
                        {
                          "handler": "headers",
                          "response": {
                            "set": {
                              "Cache-Control": [
                                "public, max-age=31536000, immutable"
                              ]
                            }
                          }
                        }
                      ],
                      "match": [
                        {
                          "path": [
                            "/_next/static/*"
                          ]
                        }
                      ]
                    },
                    {
                      "handle": [
                        {
                          "handler": "rewrite",
                          "uri": "{http.matchers.file.relative}"
                        }
                      ],
                      "match": [
                        {
                          "file": {
                            "root": "/var/www/static",
                            "try_files": [
                              "{http.request.uri.path}",
                              "{http.request.uri.path}.html",
                              "{http.request.uri.path}/"
                            ],
                            "try_policy": "first_exist"
                          }
                        }
                      ]
                    },
                    {
                      "handle": [
                        {
                          "handler": "file_server",
                          "index_names": [
                            "index.html"
                          ],
                          "root": "/var/www/static"
                        }
                      ]
                    }
                  ]
                }
              ],
              "match": [
                {
                  "host": [
                    "static.example.com"
                  ]
                }
              ],
              "terminal": true
            }
          ],
          "trusted_proxies": {
            "ranges": [
              "103.21.244.0/22",
              "2400:cb00::/32"
            ],
            "source": "static"
          }
        }
      }
    },
    "tls": {
      "automation": {
        "policies": [
          {
            "issuers": [
              {
                "module": "internal"
              }
            ]
          }
        ]
      },
      "certificates": {
        "load_files": [
          {
            "certificate": "/work/etc/origin.pem",
            "key": "/work/etc/origin.key"
          }
        ]
      }
    }
  },
  "logging": {
    "logs": {
      "access": {
        "encoder": {
          "format": "json"
        },
        "include": [
          "http.log.access.access"
        ],
        "writer": {
          "filename": "/var/log/caddy/access.log",
          "output": "file"
        }
      },
      "default": {
        "exclude": [
          "http.log.access.access"
        ]
      }
    }
  }
}

